-- td_bill_items

-- td_kot (one per order, CLOSED after billing)

-- td_kot_items (sent to the kitchen = COMPLETE)

-- td_payments (one row per tender; a split bill has two)

-- td_customer_ledger (credit sales)

-- td_stock_transactions (opening PURCHASE/IN, then SALE/OUT per bill line)
